CREATE TABLE android_metadata (locale TEXT);
CREATE TABLE alarm_templates (_id INTEGER PRIMARY KEY, external_uuid TEXT,hour INTEGER NOT NULL, minutes INTEGER NOT NULL, daysofweek INTEGER NOT NULL, blackout_start TEXT, blackout_end TEXT, enabled INTEGER NOT NULL, vibrate INTEGER NOT NULL, label TEXT NOT NULL, ringtone TEXT, delete_after_use INTEGER NOT NULL DEFAULT 0, wakeup INTEGER NOT NULL DEFAULT 0, workflow_label TEXT, workflow_data TEXT);
CREATE TABLE alarm_instances (_id INTEGER PRIMARY KEY,year INTEGER NOT NULL, month INTEGER NOT NULL, day INTEGER NOT NULL, hour INTEGER NOT NULL, minutes INTEGER NOT NULL, vibrate INTEGER NOT NULL, label TEXT NOT NULL, ringtone TEXT, alarm_state INTEGER NOT NULL, wakeup INTEGER NOT NULL DEFAULT 0, missed_reason_id INTEGER NOT NULL DEFAULT -1, missed_reason_args TEXT, alarm_id INTEGER REFERENCES alarm_templates (_id) ON DELETE CASCADE);
